insert into public.drill_blocks (pathway, level_min, level_max, youth_stage, quarter, block_order, title, content) values
  ('ntrp', 3.5, 3.5, null, 1, 1, 'Movement & Stroke Foundations', '{"tech": "Unit turn, split-step timing, grip & contact-point check — 3x10 shadow-swing reps per side to groove the unit turn, then 20 fed forehands and 20 fed backhands from the service line, checking Eastern/Semi-Western grip and contact point out in front on every rep", "tact": "Cross-court rally construction to big targets, depth awareness — live-ball cross-court rallies into a 3-cone target zone 3 ft inside the baseline; aim for a 10-ball minimum rally before the target resets and cones move; 3.5 marker: consistent depth on both forehand and backhand, not just a preferred wing", "phys": "Split-step reaction, agility ladder, balance & coordination — 4 agility-ladder patterns (2-in-2-out, lateral shuffle, crossover, ickey shuffle) x 2 passes each; 15 reaction split-steps off a coach ball-drop cue; single-leg balance holds, 20 sec per side x 2", "ment": "Between-point routine: breathe → bounce → set — rehearse the 3-step routine (one full breath, ball bounce, ready-position set) after every point in feeding drills, not just in matches, so it becomes automatic"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 1, 2, 'Rally Tolerance & Cross-Court Consistency', '{"tech": "Adjustment steps to the ball, recovery step after contact — 15 reps of a small adjustment-step-then-swing off a randomized feed, followed immediately by a recovery step back to center; repeat both wings", "tact": "Extending cross-court rallies, hitting the 3-ft-over-net deep target — cross-court rally-tolerance drill to a target line 3 ft over the net and inside the last 4 ft of the court; count consecutive balls, aim to beat last week''s best streak; 3.5 marker: sustaining 10+ ball rallies with target consistency, not just making contact", "phys": "Lateral shuffle / carioca, core stability (age-appropriate) — 4x20m lateral shuffle and carioca combo down the sideline; core circuit of plank holds (3x20 sec), bird-dogs (2x10 each side), and dead bugs (2x10 each side)", "ment": "Patience under rally pressure — redefining a ''good miss'' — after each rally drill, name one ''good miss'' out loud (an error made going for the right shot, not a rushed or lazy one) before starting the next rally"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 1, 3, 'Serve Platform, Return Basics & Benchmark 1', '{"tech": "Service motion (trophy position, gentle pronation), return split-step & block return — 3x8 shadow serves checking the trophy-position pause and pronation on contact; 20 live serves; 15 return reps starting from a timed split-step into a compact block return", "tact": "1st/2nd serve target zones (T, body, wide); deep-middle return placement — serve-target ladder: 5 balls to each of T, body, and wide zones (both boxes); return drill placing 10 returns to the deep-middle third of the court off a fed serve; 3.5 marker: reliable placement to at least two of the three serve zones under pressure", "phys": "Shoulder-safe throwing pattern drills, light rotational med-ball tosses — 2x10 overhead throwing-pattern reps with a light ball to reinforce serve mechanics; 2x8 rotational med-ball (1-2 kg) side tosses against a wall or with a partner", "ment": "Pre-serve routine; resetting after a double fault — build a fixed pre-serve routine (bounce count + breath + target pick) used on every serve in practice; after any double fault in a drill, take one breath and restate the routine before the next ball"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 2, 1, 'Topspin & Shape', '{"tech": "Low-to-high swing path; topspin forehand and two-handed backhand — 3x10 shadow swings emphasizing a clear low-to-high path and full extension to a high finish, then 20 fed topspin forehands and 20 two-handed topspin backhands, checking 3+ ft of net clearance", "tact": "Using shape/height to create time and reset points; side-to-side movement of opponent — rally drill hitting one heavy, high-shape ball per point to buy recovery time, then working the opponent corner-to-corner for 4-6 balls before finishing; 3.5 marker: topspin depth and shape on both wings, not just the stronger side", "phys": "Safe rotational core power, footwork into the shot — 2x10 med-ball rotational throws (light load) for age-appropriate power; footwork-into-contact drill — 3 steps in, swing, 3 steps out, x10 each wing", "ment": "Reframing errors as calibration; holiday-week maintenance mindset — after a miss, name what it tells you about the next shot''s adjustment rather than dwelling on the error; during the lighter holiday week, keep the routine but drop volume, not focus"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 2, 2, 'Approach Shots & Net Play', '{"tech": "Approach-shot mechanics (short backswing, deep target); continental-grip punch volley; overhead — 15 approach shots off a short feed (short backswing, deep-corner target, split-step at the transition line); 2x10 continental punch volleys each side; 10 fed overheads", "tact": "Recognizing short balls; approach + first-volley pattern; closing the net — short-ball recognition drill from live rallies (call ''short!'' and approach); 3-ball pattern of approach-shot → split-step → first volley to the open court, x10 reps; 3.5 marker: committing fully to net behind a genuine approach shot, not just occasional net trips", "phys": "Forward first-step explosiveness, reaction volleys — 10 explosive first-step sprints to a cone 6 ft away on a visual cue; 15 reaction volleys fed from close range to sharpen hands and footwork at net", "ment": "Commitment to net decisions — \"go and own it\" — before every approach-and-volley rep, say the cue phrase out loud and commit fully to closing, rather than approaching and stopping short"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 2, 3, 'Doubles Tactics & Benchmark 2', '{"tech": "Doubles ready position, poaching footwork, lob technique — 10 reps of split-step-and-cross-step poach footwork from the ad and deuce sides; 2x8 offensive lobs off a fed short ball, aiming for the back third of the court", "tact": "Serve+volley in doubles, I-formation intro, court-awareness singles vs. doubles — serve-and-volley points x8 per side; walk through I-formation starting positions and signals; contrast singles vs. doubles court boundaries and coverage using court markings; 3.5 marker: developing doubles court coverage and teamwork, a core 3.5 benchmark", "phys": "Reactive agility (poach movement), quick-twitch drills — 4x reaction-ball drops for quick-twitch response; 10 poach-movement reps reacting to a randomized visual or verbal cue", "ment": "Team communication; supporting a partner after errors — practice one clear verbal call (''mine''/''yours''/''switch'') on every doubles point; after a partner''s error, give one specific supportive phrase before the next point"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 3, 1, 'Point Construction: Building the Point', '{"tech": "Consistency under pattern pressure; direction-change mechanics — 20-ball consistency rally under a set pattern (cross-court only) before allowing errors; 3x8 direction-change reps (cross-court in, down-the-line out) focusing on early prep on the change", "tact": "3-ball patterns (serve+1, rally+1, finish); cross-court vs. down-the-line decision rules — drill the serve+1 pattern (serve, put-away 2nd ball) x10; rally+1 pattern (rally 3 balls, finish on the 4th) x10; review the cross-court-safe / down-the-line-on-a-short-or-wide-ball decision rule; 3.5 marker: constructing 3+ ball patterns on purpose, not just reacting ball to ball", "phys": "Multi-directional footwork combinations — ladder-plus-cone combo drill mixing forward, lateral, and backward movement patterns, 4 combinations x 2 reps each", "ment": "Playing \"the point before the point\" — pre-point planning — before each point in a drill or practice set, state a one-sentence plan out loud (e.g., ''serve wide, follow to the open court'') before playing it out"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 3, 2, 'Defense – Neutral – Attack Framework', '{"tech": "Defensive slice / high-ball response; offensive contact point on short balls — 15 defensive slice reps off a deep, high fed ball; 15 reps stepping in on short balls to take the ball early and drive it, checking an earlier, higher contact point", "tact": "Reading ball height/depth to classify defend / neutral / attack; recovery positioning by ball type — call-and-react drill: coach feeds balls of varying height/depth, player calls ''defend'', ''neutral'', or ''attack'' and plays the shot, then recovers to the matching court position; 3.5 marker: correctly classifying and reacting to ball height/depth in live play", "phys": "Transition footwork (in/out movement), recovery sprints — 10 in-and-out transition reps (2 steps in to attack, 3 steps back to recover); 6x10m recovery sprints back to center after a wide ball", "ment": "Staying composed while defending; patience-to-aggression shift — practice staying neutral (no rushed shots) for 3-5 defensive balls before looking to shift to attack on a clear opportunity ball"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 3, 3, 'Tournament Prep I & Benchmark 3', '{"tech": "Match-speed stroke reliability; efficient warm-up routine — full-speed rally reps (20 balls, both wings) at tournament pace; practice the complete pre-match warm-up sequence (groundstrokes, volleys, overheads, serves, returns) in 10 minutes", "tact": "Adjusting to opponent style (pusher / hitter / net-rusher); simple game plans — practice sets against each opponent archetype (fed or with a hitting partner), applying one simple game plan per style (e.g., extend rallies vs. a pusher, take pace off vs. a hitter); 3.5 marker: holding technique and game plans at match speed, not just in drilling", "phys": "Age-appropriate match-fitness intervals; hydration & nutrition basics — interval sets of 20-sec high-intensity movement / 40-sec rest x8 to mirror point-and-rest match rhythm; review a simple pre-match hydration and snack checklist", "ment": "Pre-match routine, changeover routine, handling nerves — rehearse a full pre-match routine (arrival, warm-up, mental checklist) and a 90-second changeover routine (towel, water, one cue word) during practice sets"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 4, 1, 'Advanced Serve/Return Systems', '{"tech": "Kick and slice serve variety; aggressive second-serve return; placement disguise — 2x10 kick serves and 2x10 slice serves focusing on distinct toss positions; 15 aggressive second-serve return reps stepping in and driving the return; disguise drill keeping toss/prep identical across serve types", "tact": "Serve-pattern sequencing; return positioning by serve type — sequence 3 serves per game plan (e.g., wide-body-wide) and track success; return-position drill adjusting stance and target based on whether the serve is flat, kick, or slice; 3.5 marker: adding a 2nd serve type (kick or slice) with real disguise", "phys": "Explosive rotational power (safe progressions), shoulder care / prehab — 2x8 rotational med-ball throws at controlled tempo; shoulder prehab band circuit (external rotation, Y-T-W raises) 2x12 each", "ment": "Big-point serve routine; return focus reset — practice an extended, extra-deliberate routine specifically for break points and set points; on return, use one reset breath before every big point"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 4, 2, 'Big-Point Mental Game & Momentum Management', '{"tech": "Maintaining technique under fatigue — preventing breakdown — fed rallies at the end of a fitness set (post-sprint) to rehearse holding stroke mechanics (unit turn, contact point) while tired", "tact": "Recognizing momentum shifts; mid-match tactical adjustments; tiebreak strategy — practice sets with a mid-set ''momentum check-in'' (what changed, what adjustment to make); dedicated tiebreak practice points working serve/return priority patterns; 3.5 marker: maintaining shot quality under fatigue and pressure, not just when fresh", "phys": "Fatigue-resistance conditioning; recovery & mobility emphasis — extended interval circuit (30-sec work / 30-sec rest x10) at the end of a session; 10-min mobility/stretch cool-down focusing on hips, shoulders, and hamstrings", "ment": "Between-point routine mastery, self-talk, visualization, resetting after bad calls — full between-point routine under simulated pressure (crowd noise, score pressure); one visualization rep before serve/return games; scripted response for a bad-call scenario"}'::jsonb),
  ('ntrp', 3.5, 3.5, null, 4, 3, 'Competitive Peak, Taper & Year-End Benchmark', '{"tech": "Fine-tuning / maintenance only — no new mechanics, reliability focus — short, high-quality maintenance reps (10-15 per stroke) on existing mechanics only, no new technical work introduced this block", "tact": "Full game-plan execution; opponent scouting applied; doubles + singles integration — full practice sets executing a written game plan against a known opponent profile; alternate singles and doubles sets to integrate both skill sets heading into year-end matches; 3.5 marker: full game-plan execution across both singles and doubles at a 3.5 standard", "phys": "Taper — reduced physical load, freshness priority — reduce conditioning volume by roughly a third versus peak blocks; prioritize short, sharp activation work over long conditioning sessions", "ment": "Peak-performance routine; season-review goal-setting for Year 2 — rehearse the full peak-performance routine (pre-match through changeovers) in every practice set; end the block with a written season review and 3 goals for Year 2"}'::jsonb),
  ('youth', null, null, 'red_starter', 1, 1, 'Red Starter', '{"name": "Red Starter", "blurb": "Ball tracking, balance, catching, and first taps with the racquet — no rallying pressure yet, just games. (NTRP 2.5 track: starting already comfortable with basic ball control, so this stage moves a little faster than a first-time beginner''s.)", "badges": ["Bounce & Catch", "Ready-Position Freeze Game", "Balloon Volley Rally", "Rolling-Ball Scoop Pickup", "Underhand Toss to a Target", "Racquet Balance Walk"], "skill": ["Bounce a ball and catch it in a cup or hand, 5 times in a row — use a soft foam ball and a plastic cup, stand still, count each bounce out loud", "Practice the ''freeze'' ready position on a clap or whistle cue — knees bent, racquet up, 10 freeze reps mixing claps and whistles", "Volley a balloon back and forth without letting it touch the ground — start 3 ft apart, count consecutive hits together, take a step back after 5", "Scoop up rolling balls with the racquet face, no hands — roll 10 balls from 6 ft away, scoop each one onto the strings and carry it to a hoop", "Underhand toss a ball into a hoop or box target — 10 tosses from 5 ft, move the hoop farther after 3 makes in a row", "Balance a ball on the racquet while walking a line — walk a 10-ft cone line and back 3 times without dropping the ball"], "rally": ["Bounce-and-catch relay race with a partner — two teams race to bounce-and-catch 5 times each down a 10-ft lane", "Balloon rally: keep it up as a team, count together — everyone counts out loud, celebrate a new team best", "Roll-and-catch with a partner across a short distance — 8-ft gap, 10 rolls each way, switch to bounce-roll after 5", "Toss-and-catch over a low rope or line — rope at waist height, 10 tosses each, step back after 5 in a row", "Freeze-tag ready position game — coach calls freeze at random moments during light movement; best freeze wins a point", "Animal-walk footwork game to the net and back — bear crawl, crab walk, and bunny hop, each once down and back"], "play": ["Sticker chart check: which skills are ''green light'' today? — pick 2 skills to demo for a sticker", "Team balloon-keepy-uppy challenge, beat yesterday''s count — write today''s record on the chart", "Obstacle course mixing today''s skills — 4 stations, one lap each, timed for fun not speed", "Simon Says with tennis ready positions — 8 rounds mixing ready position, freeze, and racquet-up cues", "Coach vs. kid toss-and-catch challenge — first to 10 catches wins; best of 3 rounds", "Show-and-tell: demonstrate one badge skill to a grown-up — pick the skill closest to earning a badge"]}'::jsonb),
  ('youth', null, null, 'red_rally', 2, 1, 'Red Rally', '{"name": "Red Rally", "blurb": "First real racquet-and-ball rallying on the mini (36-ft) red-ball court, plus first serves. (NTRP 2.5 track: rally and rep targets run higher than the standard pathway — 5-9 in a row instead of 3-7.)", "badges": ["Self-Bounce Rally (3 hits)", "Forehand Contact Point", "Backhand Contact Point", "Sideways Shuffle Steps", "Mini-Court Feed Rally (5 balls)", "Drop-and-Hit Serve"], "skill": ["Bounce the ball off the racquet 5 times in a row, self-fed — build to 8 in a row before moving on, both flat and slight bounce", "Forehand: hit a fed ball back over a low net to a target — 15 fed forehands aiming at a hoop or cone 10 ft away", "Backhand: hit a fed ball back over a low net to a target — 15 fed two-handed backhands aiming at the same target", "Sideways shuffle steps to reach a ball, no crossing feet — 10 shuffle reps each direction to a cone, then back to center", "Rally with the coach, catch-feed style, 7 balls in a row — build from catch-and-toss to full racquet rally over a few sessions", "Practice a simple drop-and-hit serve into the box — 10 drop-and-hit serves, count how many land in the service box"], "rally": ["Mini-court rally game: how many in a row? — 36-ft mini court, write down the best rally streak each session", "Forehand target game — hit the cone, score a point — 10 fed balls, 1 point per cone hit, 2 for a direct knock-down", "Backhand target game — hit the cone, score a point — same setup on the backhand wing", "Shuffle-step shadow game before every rally — 5 shuffle steps to a marked spot before each rally point starts", "Coach-feed rally ladder: 5, then 7, then 9 in a row — move up a rung only after hitting the current target twice", "Serve ladder: serve into 3 different colored zones — 3 serves per zone, ladder resets if 2 in a row miss"], "play": ["Mini-match: first to 5 points, underhand serves allowed — play best of 3 mini-matches", "Rally-counting contest with a partner — 3 rounds, keep the highest streak on the chart", "Team rally relay — keep the ball going across 3 players — rotate positions every 5 hits", "Serve-and-catch mini game — 1 point per serve landed in the box and caught cleanly", "Badge check-in: try for a new badge today — pick one badge from this stage to attempt", "Fun match with silly bonus points for good ready position — +1 bonus point for a clean freeze before each return"]}'::jsonb),
  ('youth', null, null, 'red_game_player', 3, 1, 'Red Game Player', '{"name": "Red Game Player", "blurb": "Real mini-tennis scoring, court positioning, and the first lessons in sportsmanship. (NTRP 2.5 track: real scoring and two-bounce awareness should feel familiar, not brand new.)", "badges": ["Count-to-7 Scoring", "Two-Bounce Rule Understanding", "Court Position Awareness", "Doubles Teamwork Game", "Good-Sport Handshake", "Call-Your-Own-Line Honesty"], "skill": ["Practice counting score out loud during a mini-game — call the score before every point, both players", "Two-bounce rule drills — when is the point over? — 10 live points, call ''out'' the moment a 2nd bounce happens", "Practice moving back to the middle after every shot — 10 rally balls, checking a return-to-center step each time", "Doubles positioning game with a partner — walk through deuce/ad side spots, then play 5 doubles points", "Practice a good-sport handshake and ''good shot!'' — rehearse after every practice point, win or lose", "Practice calling a ball in/out honestly during a drill — 10 close-line balls with a coach confirming each call"], "rally": ["Mini-match with the player keeping their own score — full mini-match, player calls the score aloud", "Two-bounce scramble game — points restart if either side lets it bounce twice", "Center-recovery rally game — bonus point for tagging the center cone between every shot", "Doubles mini-game, 2v1 or 2v2 with a helper — rotate every 2 points so everyone serves and returns", "Rally + handshake ritual after every game — no game ends without the handshake and ''good shot''", "Line-calling practice game with cones as lines — 10 balls landing near the cone ''line'', practice fair calls"], "play": ["Full mini-match on the red-ball court, real scoring — best of 3 games, real scoring rules", "Team doubles mini-tournament with friends/siblings — round-robin, everyone plays 2 matches", "''Good sport of the day'' award game — award goes to the best handshake/attitude, not the winner", "Best-of-3 mini-games with handshakes after each — 3 short games back to back", "Court-awareness obstacle relay — race through cones marking singles/doubles lines and key spots", "Badge check-in: mini-match performance review — coach notes one strength and one focus area"]}'::jsonb),
  ('youth', null, null, 'orange_ready', 4, 1, 'Orange Ready', '{"name": "Orange Ready", "blurb": "Stretching rallies longer, first shot-selection ideas, and getting comfortable on the bigger orange-ball court. (NTRP 2.5 track: season target is an 8-12 ball rally streak and 4 serves in a row inside the box by Check-In 4.)", "badges": ["Sustained Rally (5+ both sides)", "Move-Up on a Short Ball", "Stay-Back on a Deep Ball", "Play a Mini-Tournament", "Orange-Ball Comfort Rally", "Serve Into the Box (3 in a row)"], "skill": ["Sustained rally with the coach, 8+ balls each side — build toward a 12+ ball rally by stage end (NTRP 2.5 rally streak)", "''Short ball, move up!'' recognition game — 10 mixed feeds, call ''short'' and step in on the right ones", "''Deep ball, stay back!'' recognition game — 10 mixed feeds, call ''deep'' and hold ground on the right ones", "Practice tournament routines: warm-up, score, handshake — full dry run of match-day routine, start to finish", "First rallies on the bigger orange-ball court — 10 rally points adjusting to the longer court and bigger targets", "Serve practice: land 4 in a row inside the box — from both the deuce and ad sides"], "rally": ["Rally-extension ladder: beat your longest rally — track and beat last week''s best streak", "Short-ball vs. deep-ball sorting game — 12 fed balls, sort and react correctly to at least 9", "Orange-court rally with more running room — 10 rally points using the full width of the court", "Serve ladder on the orange court — 3 serves per zone across 3 zones, same ladder rules as before", "Mixed red/orange ball rally challenge — alternate ball types every 5 shots to build adaptability", "Partner rally with a shot-selection call-out game — call ''forehand'' or ''backhand'' before each shot lands"], "play": ["Mini-tournament day — real matches, real scoring — round-robin or bracket, full mini-match rules", "Orange-ball fun match — first full match on the bigger court with orange balls", "Season badge ceremony rehearsal — practice the walk-up and badge presentation for the real ceremony", "Serve challenge contest — most serves landed in 10 tries, prizes for personal bests", "Longest-rally leaderboard game — post today''s best rally on the family leaderboard", "Celebration match: play every skill learned this year — a fun match mixing in every stage''s signature skill"]}'::jsonb),
  ('ntrp', 1.0, 1.5, null, 1, 1, 'Grip, Ball Familiarity & Court Orientation', '{"tech": "Grip basics (forehand/backhand changes), ball-bounce control, contact-point awareness via fed short-court reps", "tact": "Rally shape is simple — get the ball back over the net anywhere in the opposite court", "phys": "Basic split-step introduction, general coordination and agility-ladder games", "ment": "Staying relaxed around contact, no score pressure yet"}'::jsonb),
  ('ntrp', 1.0, 1.5, null, 2, 1, 'Continuous Play & Short-Court Rallying', '{"tech": "Continuous fed-ball rallies from mini/short court, forehand and backhand basics on both wings", "tact": "Keeping the ball in play for 2-3 shots, aiming toward the middle of the court", "phys": "Simple footwork patterns (shuffle to the ball), balance games", "ment": "Patience with errors, celebrating any rally that happens"}'::jsonb),
  ('ntrp', 1.0, 1.5, null, 3, 1, 'Serve Introduction & Basic Positions', '{"tech": "Underhand or modified serve toss-and-hit into a short box, continued rally consistency", "tact": "Learning basic singles court boundaries and where to stand", "phys": "Coordination games, light agility work", "ment": "Following simple scoring/game rules for the first time"}'::jsonb),
  ('ntrp', 1.0, 1.5, null, 4, 1, 'First Mini-Matches', '{"tech": "Consolidating forehand/backhand/serve basics under light pressure", "tact": "Playing out simple points with modified scoring", "phys": "General movement conditioning appropriate for brand-new players", "ment": "Good-sport habits — handshakes, enjoying competition over winning"}'::jsonb),
  ('ntrp', 2.0, 2.5, null, 1, 1, 'Consistent Contact & Court Positions', '{"tech": "Consistent contact-point reps on both wings off a fed ball", "tact": "Introducing basic singles and doubles positioning", "phys": "Split-step timing, agility-ladder work", "ment": "Staying composed through repeated misses while the stroke develops"}'::jsonb),
  ('ntrp', 2.0, 2.5, null, 2, 1, 'Short-Rally Consistency', '{"tech": "Sustaining short rallies (3-5 balls) off a fed or light partner feed", "tact": "Aiming shots toward the middle of the court for safety and consistency", "phys": "Lateral movement drills, basic core stability", "ment": "Redefining a ''good miss'' — reward good swings, not just results"}'::jsonb),
  ('ntrp', 2.0, 2.5, null, 3, 1, 'Serve-In & Simple Scoring', '{"tech": "Full service motion introduction, working toward landing serves in the box", "tact": "Simple scoring and basic point patterns", "phys": "Light throwing-pattern drills for serve mechanics", "ment": "Pre-serve routine basics, staying calm after a fault"}'::jsonb),
  ('ntrp', 2.0, 2.5, null, 4, 1, 'First Real Matches', '{"tech": "Applying rally and serve basics in live points", "tact": "Playing full games with real scoring", "phys": "Match-appropriate movement conditioning", "ment": "Sportsmanship — handling both wins and losses well"}'::jsonb),
  ('ntrp', 3.0, 3.0, null, 1, 1, 'Medium-Pace Consistency', '{"tech": "Consistent medium-paced forehand and backhand off a fed ball, direction mostly toward the middle", "tact": "Building simple, sustained cross-court rallies", "phys": "Agility and split-step reaction drills", "ment": "Patience through longer rallies rather than forcing an early finish"}'::jsonb),
  ('ntrp', 3.0, 3.0, null, 2, 1, 'Backhand Catch-Up & Direction', '{"tech": "Extra reps building backhand reliability toward matching the forehand", "tact": "Introducing basic directional control beyond just the middle", "phys": "Lateral shuffle and core-stability work", "ment": "Staying confident hitting to and from the weaker wing"}'::jsonb),
  ('ntrp', 3.0, 3.0, null, 3, 1, 'Serve Zones & Simple Point Patterns', '{"tech": "Serve placement basics: T, body, and wide targets", "tact": "Simple serve+return patterns", "phys": "Throwing-pattern drills to reinforce serve mechanics", "ment": "Pre-serve routine, resetting calmly after a fault"}'::jsonb),
  ('ntrp', 3.0, 3.0, null, 4, 1, 'Competing at 3.0', '{"tech": "Applying consistent strokes and serve zones under match play", "tact": "Simple point construction — get it in, then look to direct it", "phys": "Match-fitness intervals appropriate to the level", "ment": "Between-point routine basics"}'::jsonb),
  ('ntrp', 4.0, 4.0, null, 1, 1, 'Depth & Direction on Both Wings', '{"tech": "Dependable forehand and backhand with directional control and real depth", "tact": "Constructing rallies with purposeful depth, not just direction", "phys": "Footwork into the shot, core rotation", "ment": "Committing to a shot plan before hitting rather than deciding mid-swing"}'::jsonb),
  ('ntrp', 4.0, 4.0, null, 2, 1, 'Net Game Reliability', '{"tech": "Approach shots, volleys, and overheads that work most of the time", "tact": "Recognizing short balls and closing the net with purpose", "phys": "Forward first-step explosiveness, reaction volleys", "ment": "Full commitment to net decisions once made"}'::jsonb),
  ('ntrp', 4.0, 4.0, null, 3, 1, 'Serve+1 & Point Construction', '{"tech": "Reliable serve placement supporting a planned follow-up shot", "tact": "Serve+1 and rally+1 patterns", "phys": "Multi-directional footwork combinations", "ment": "Playing ''the point before the point'' — a plan before every point"}'::jsonb),
  ('ntrp', 4.0, 4.0, null, 4, 1, 'Competing at 4.0', '{"tech": "Consolidating depth, net play, and serve patterns under match pressure", "tact": "Full game-plan application against different opponent styles", "phys": "Match-fitness conditioning", "ment": "Composure across a full match, not just a hot streak"}'::jsonb),
  ('ntrp', 4.5, 4.5, null, 1, 1, 'Power & Spin Development', '{"tech": "Developing topspin and slice variety with more pace", "tact": "Using spin and pace deliberately to control rally tempo", "phys": "Safe rotational power work, footwork efficiency", "ment": "Staying patient while adding power, not sacrificing control for it"}'::jsonb),
  ('ntrp', 4.5, 4.5, null, 2, 1, 'Handling Pace & Footwork', '{"tech": "Taking the ball earlier to handle faster incoming pace", "tact": "Redirecting pace rather than passively absorbing it", "phys": "Reactive agility, split-step timing under pressure", "ment": "Composure against bigger hitters"}'::jsonb),
